<?php defined('BASEPATH') or exit('No direct script access allowed');$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($suffix='')=>CompanyRequestScope::adminUrl($this,'company_project_portal_rules'.$suffix);$company_page_title='Regras do projeto no portal';require __DIR__.'/layout_head.php'; ?>
<h1>Regras do projeto no portal</h1><?php if($error){ ?><p role="alert"><?= $esc($error); ?></p><?php }if($state){$p=$state['project'];$r=$state['rules'];$labels=['view_tasks'=>'Ver tarefas publicadas','view_task_comments'=>'Ver comentários publicados','view_task_checklist_items'=>'Ver itens publicados da checklist','view_task_attachments'=>'Ver anexos publicados','view_task_total_logged_time'=>'Ver soma dos tempos encerrados publicados','view_team_members'=>'Ver nome do responsável autorizado da tarefa'];$hidden=function($action)use($esc,$p,$r,$company_project_rules_csrf){echo '<input type="hidden" name="company_project_rules_csrf" value="'.$esc($company_project_rules_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'"><input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="project_id" value="'.(int)$p['id'].'"><input type="hidden" name="project_revision" value="'.(int)$p['revision'].'"><input type="hidden" name="rules_revision" value="'.(int)$r['revision'].'">';}; ?>
<p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_projects?project='.(int)$p['id'])); ?>">Voltar ao projeto</a></p><h2><?= $esc($p['name']); ?></h2>
<p>O contato precisa da permissão nativa de projetos e pertencer ao cliente privado deste projeto. Publique o projeto antes das tarefas. Cada tarefa e cada comentário, item da checklist, anexo ou tempo exige revisão e publicação própria. Novas versões de tarefa ficam privadas até nova revisão. Estas seis regras controlam consulta. Ações do contato exigem autorização separada abaixo, sem publicar automaticamente tarefas ou filhos.</p>
<?php if($state['can_edit']){ ?><?= form_open($url());$hidden('save_rules');foreach($labels as $field=>$label){ ?><label style="display:block"><input type="checkbox" name="<?= $esc($field); ?>" value="1" <?= $r[$field]?'checked':''; ?>> <?= $esc($label); ?></label><?php } ?><p>Mantenha “Ver tarefas” marcado para ativar qualquer regra abaixo dele. Os dados internos não são publicados por estes flags.</p><button type="submit">Salvar regras</button><?= form_close(); ?><?= form_open($url());$hidden('hide_tasks'); ?><button type="submit">Ocultar todas as tarefas no portal</button><?= form_close(); ?><?php } ?>
<?php if(is_array($write_state??null)){require APPPATH.'views/admin/companies/project_task_write_rules.php';} ?><h3>Tarefas</h3><?php if(!$state['can_tasks']){ ?><p>É necessária permissão de consulta de tarefas para revisar publicações.</p><?php }else{foreach($state['tasks'] as $t){ ?><p><a href="<?= $esc($url('?project='.(int)$p['id'].'&task='.(int)$t['id'])); ?>"><?= $esc($t['name']); ?></a> — <?= (int)$t['visible']===1&&(int)$t['task_revision']===(int)$t['revision']?'Publicada na revisão atual':'Privada ou aguardando revisão'; ?></p><?php }} ?>
<?php if($state['next']!==null){ ?><a href="<?= $esc($url('?project='.(int)$p['id'].'&after='.(int)$state['next'])); ?>">Mais tarefas para revisar</a><?php }if($state['task']){$task=$state['task'];$t=$state['task_publication'];$pub=$t&&(int)$t['visible']===1&&(int)$t['task_revision']===(int)$task['revision'];$publicationForm=function($kind,$key,$visible,$label)use($url,$hidden,$task,$esc,$state){if(!$state['can_edit'])return;echo form_open($url());$hidden('publish');echo '<input type="hidden" name="task_id" value="'.(int)$task['id'].'"><input type="hidden" name="task_revision" value="'.(int)$task['revision'].'"><input type="hidden" name="kind" value="'.$esc($kind).'"><input type="hidden" name="child_key" value="'.$esc($key).'"><label><input type="checkbox" name="visible" value="1" '.($visible?'checked':'').'> '.$esc($label).'</label> <button type="submit">Salvar publicação</button>'.form_close();}; ?>
<?php if(is_array($task_authorship??null)){require APPPATH.'views/admin/companies/project_task_authorship.php';} ?><h3>Revisar: <?= $esc($task['name']); ?></h3><p style="white-space:pre-wrap"><?= $esc($task['description']); ?></p><?php $publicationForm('task','',$pub,'Publicar esta revisão da tarefa');foreach($state['children'] as $child){$source=$child['source'];$label=match($child['kind']){'comment'=>'Comentário: '.$source['body'],'checklist'=>'Checklist: '.$source['text'],'file'=>'Anexo: '.$source['filename'],'timer'=>'Tempo encerrado: '.(int)$source['seconds'].' segundos',default=>''};$publicationForm($child['kind'],$child['key'],$child['visible'],$label);}}} ?>
